60	/** A claim's status change (open, settle, approve, reject or void), shared by the single and the bulk actions. Every
61	 *  check is made before anything is written, so a refusal writes nothing to the store or the audit. */
62	final class ClaimStatusChange {
63	    private ClaimStatusChange() {
64	    }
65	
66	    static Claim apply(String id, long cid, String action, String by, ClaimRepository repository,
67	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
68	        return apply(id, cid, action, null, by, repository, periods, settings, audit, rollup);
69	    }
70	
71	    static Claim apply(String id, long cid, String action, String reason, String by, ClaimRepository repository,
72	            PeriodRepository periods, SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
73	        if ("resettle".equals(action == null ? "" : action.trim())) {
74	            return resettle(id, cid, by, repository, periods, settings, audit, rollup);
75	        }
76	        String to;
77	        List<String> from;
78	        String event;
79	        switch (action == null ? "" : action.trim()) {
80	            case "open" -> { to = "OPEN"; from = List.of("DRAFT"); event = "CLAIM_OPENED"; }
81	            case "settle" -> { to = "SETTLED"; from = List.of("OPEN"); event = "CLAIM_SETTLED"; }
82	            case "approve" -> { to = "SETTLED"; from = List.of("PENDING"); event = "CLAIM_APPROVED"; }
83	            case "reject" -> { to = "OPEN"; from = List.of("PENDING"); event = "CLAIM_REJECTED"; }
84	            case "void" -> { to = "VOID"; from = List.of("DRAFT", "OPEN", "PENDING"); event = "CLAIM_VOIDED"; }
85	            default -> throw new BadRequestException("no such action");
86	        }
87	        Claim found = repository.find(id, cid);
88	        if (found == null) {
89	            throw new BadRequestException("no such claim");
90	        }
91	        if (!from.contains(found.status())) {
92	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
93	        }
94	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
95	        // Four eyes: whoever opened a claim cannot settle it.
96	        if (to.equals("SETTLED") && found.status().equals("OPEN") && by.equals(found.openedBy())) {
97	            throw new BadRequestException("the user who opened a claim cannot settle it");
98	        }
99	        // A deferred claim cannot be settled until the sheet's today reaches the date it is deferred until.
100	        if (to.equals("SETTLED") && found.deferred()) {
101	            throw new BadRequestException("a claim deferred until " + found.deferredUntil() + " cannot be settled");
102	        }
103	        // Only a steward approves or rejects a PENDING claim, and never one they opened themselves.
104	        if (found.status().equals("PENDING") && !to.equals("VOID")) {
105	            if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
106	                throw new BadRequestException("only a steward can " + action.trim() + " a pending claim");
107	            }
108	            if (to.equals("SETTLED") && by.equals(found.openedBy())) {
109	                throw new BadRequestException("the user who opened a claim cannot approve it");
110	            }
111	        }
112	        String why = reason == null ? "" : reason.trim();
113	        if (event.equals("CLAIM_REJECTED") && why.isEmpty()) {
114	            throw new BadRequestException("give a reason to reject the claim");
115	        }
116	        // A clerk settles outright only a claim whose due is within the sheet's clerk limit ('n/a' is within
117	        // any); above it the claim goes to PENDING for a steward to approve or reject. A steward settles anything.
118	        if (to.equals("SETTLED") && found.status().equals("OPEN")
119	                && settings.role(id, by).equals(SettingsRepository.CLERK)) {
120	            BigDecimal limit = settings.clerkLimit(id);
121	            BigDecimal now = repository.dueNow(id, found);
122	            if (limit != null && now != null && now.compareTo(limit) > 0) {
123	                to = "PENDING";
124	                event = "CLAIM_PENDING";
125	            }
126	        }
127	        Rollup.Snapshot before = rollup.take(id);
128	        if (!repository.changeStatus(id, cid, from, to)) {
129	            throw new BadRequestException("a " + found.status() + " claim cannot be moved to " + to);
130	        }
131	        // Opening gives the sheet's next number; a rejected claim keeps its own; a voided claim keeps the number it had (never reused).
132	        String number = found.number();
133	        String openedBy = found.openedBy();
134	        if (found.status().equals("DRAFT") && to.equals("OPEN")) {
135	            number = repository.numbersPerPeriod(id)
136	                    ? repository.numberInPeriod(id, cid, LocalDate.parse(found.date()))
137	                    : repository.number(id, cid);
138	            repository.openedBy(id, cid, by);
139	            openedBy = by;
140	        }
141	        // Settling (or approving) fixes the claim's due as it is now: the figure its last statement bound it to
142	        // (a PENDING claim's is live), else its live due ('n/a' when its grade has no rate, which stays live), with its late charge frozen in.
143	        String due = null;
144	        String tail = event.equals("CLAIM_REJECTED") ? " reason=" + why : "";
145	        if (to.equals("SETTLED")) {
146	            BigDecimal now = repository.dueNow(id, found);
147	            repository.settleDue(id, cid, now);
148	            due = ClaimRepository.dueOf(now);
149	            tail = " due=" + (due == null ? "n/a" : due);
150	        }
151	        repository.log(id, cid, by);
152	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), to,
153	                number, due, openedBy, found.stated(), found.statedDue(), found.corrects(), found.dueBy(),
154	                found.statedNa(), found.deferredUntil(), found.deferred());
155	        audit.record(event + " sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
156	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(number) + tail);
157	        rollup.record(id, by, before);
158	        return changed;
159	    }
160	
161	    /** A steward re-settles a SETTLED claim (not in a closed period): its due is frozen again at the figure it would
162	     *  have today as an open claim bound by no statement (today's rates, grades, floor and late charge). */
163	    private static Claim resettle(String id, long cid, String by, ClaimRepository repository, PeriodRepository periods,
164	            SettingsRepository settings, Audit audit, Rollup rollup) throws BadRequestException {
165	        Claim found = repository.find(id, cid);
166	        if (found == null) {
167	            throw new BadRequestException("no such claim");
168	        }
169	        if (!settings.role(id, by).equals(SettingsRepository.STEWARD)) {
170	            throw new BadRequestException("only a steward can re-settle a claim");
171	        }
172	        if (!found.status().equals("SETTLED")) {
173	            throw new BadRequestException("only a SETTLED claim can be re-settled");
174	        }
175	        PeriodGuard.open(periods, id, LocalDate.parse(found.date()));
176	        Claim live = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(), "OPEN",
177	                found.number(), null, found.openedBy(), false, null, found.corrects(), found.dueBy(), false, null, false);
178	        BigDecimal now = repository.dueNow(id, live);
179	        Rollup.Snapshot before = rollup.take(id);
180	        repository.settleDue(id, cid, now);
181	        repository.log(id, cid, by);
182	        String old = found.due() == null ? "n/a" : found.due();
183	        String due = ClaimRepository.dueOf(now);
184	        Claim changed = new Claim(found.id(), found.personId(), found.amount(), found.date(), found.note(),
185	                found.status(), found.number(), due, found.openedBy(), found.stated(), found.statedDue(),
186	                found.corrects(), found.dueBy(), found.statedNa(), found.deferredUntil(), found.deferred());
187	        audit.record("CLAIM_RESETTLED sheet=" + id + " by=" + by + " person=" + repository.personName(id, found.personId())
188	                + " amount=" + changed.amount() + " date=" + changed.date() + Claim.auditNumber(found.number())
189	                + " old=" + old + " new=" + (due == null ? "n/a" : due));
190	        rollup.record(id, by, before);
191	        return changed;
192	    }
193	}
