196	import java.util.List;
197	import net.officefloor.hq.app.person.Hold;
198	
199	/** A claim of a person on a sheet: its amount with two decimals, its date (ISO yyyy-MM-dd), note and status
200	 *  (DRAFT, OPEN, PENDING — a clerk's settle above the clerk limit, awaiting a steward — SETTLED or VOID), its number on the sheet (a sheet-wide 1, 2, ... or, under period numbering, <period>-<n> or X-<n>; null while a draft; a voided claim keeps the one it had), and the due fixed when it was settled
201	 *  (null unless settled with a rate; its due is then worked out live from the rates), and who opened it
202	 *  (null until it is opened), whether its person's last statement bound it, and the figure it was bound to
203	 *  (null when not bound, or bound with no figure: its due then stays live), and, for a correction (a negative
204	 *  amount), the number of the settled claim it corrects (null otherwise), and its due-by (yyyy-MM-dd: fixed when it was
205	 *  created, its date then plus the terms of its person's grade on that date, else the sheet's terms), and
206	 *  whether its last statement bound it to n/a (the rate that would apply to it had ended: its due then
207	 *  stays n/a, not live), and the date it is deferred until (null when never deferred) and whether it is
208	 *  deferred now (OPEN and that date after the sheet's today: it then counts in no total, is not overdue,
209	 *  cannot be settled and a statement leaves it unbound). */
210	public record Claim(long id, long personId, String amount, String date, String note, String status,
211	        String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
212	        String dueBy, boolean statedNa, String deferredUntil, boolean deferred) {
213	
214	    /** Whether the claim is open: OPEN, or PENDING (handled like OPEN everywhere but its statement binding). */
215	    public boolean open() {
216	        return status.equals("OPEN") || status.equals("PENDING");
217	    }
218	
219	    /** Whether the claim counts toward claimed and every total: only open (OPEN or PENDING) and SETTLED claims do. */
220	    public boolean counts() {
221	        return open() || status.equals("SETTLED");
222	    }
223	
224	    /** Whether the claim counts toward live totals (claimed, due-totals, a period's total) given its
225	     *  person's holds: an open claim dated within a hold does not, unless a statement binds it; SETTLED
226	     *  claims always do. A deferred claim does not. */
227	    public boolean counts(List<Hold> holds) {
228	        return status.equals("SETTLED") || (open() && !deferred && (bound() || !Hold.anyCovers(holds, date)));
229	    }
230	
231	    /** Whether the claim keeps a fixed figure: its settled due, else the one its last statement bound it
232	     *  to — except while PENDING, when the statement does not bind it and its figure is live. */
233	    public boolean fixed() {
234	        return due != null || (bound() && statedDue != null);
235	    }
236	
237	    /** Whether its last statement binds it now: it was stated and is not PENDING. */
238	    public boolean bound() {
239	        return stated && !status.equals("PENDING");
240	    }
241	
242	    /** The audit field a numbered claim adds at the end of its lines: " number=<n>", or "" when it has none. */
243	    static String auditNumber(String number) {
244	        return number == null ? "" : " number=" + number;
245	    }
246	}
