323	/** Save the settings given. A setting with a figure is recorded from its from-date (the sheet's today when
324	 *  none is given), replacing a value recorded from that date and keeping the others; its record ends with
325	 *  from=<date> when a from-date was given. */
326	public class SaveSettings {
327	    public void save(@PathVariable("sheetId") String sheetId, @Val SettingsInput input,
328	            ServerHttpConnection connection, SettingsRepository repository, SheetRepository sheets, Audit audit,
329	            Rollup rollup, Out<Settings> settings) throws BadRequestException {
330	        String by = CurrentUser.require(connection);
331	        String id = sheetId == null ? "" : sheetId.trim();
332	        if (!repository.sheetExists(id)) {
333	            throw new BadRequestException("no such sheet");
334	        }
335	        LocalDate today = sheets.today(id);
336	        Rollup.Snapshot before = rollup.take(id);
337	        String prefix = "SETTING_CHANGED sheet=" + id + " by=" + by + " key=";
338	        if (input.setsClerkLimit()) {
339	            repository.setClerkLimit(id, from(input, "clerk-limit", today), input.clerkLimit());
340	            audit.record(prefix + "clerk-limit value="
341	                    + (input.clerkLimit() == null ? "" : SettingsRepository.money(input.clerkLimit())) + given(input, "clerk-limit"));
342	        }
343	        if (input.setsFloor()) {
344	            repository.setFloor(id, from(input, "floor", today), input.floor());
345	            audit.record(prefix + "floor value=" + SettingsRepository.money(input.floor()) + given(input, "floor"));
346	        }
347	        if (input.setsTerms()) {
348	            repository.setTerms(id, from(input, "terms", today), input.terms());
349	            audit.record(prefix + "terms value=" + input.terms() + given(input, "terms"));
350	        }
351	        input.gradeTerms().forEach((grade, terms) -> {
352	            repository.setGradeTerms(id, grade, from(input, "terms-" + grade, today), terms);
353	            audit.record(prefix + "terms-" + grade + " value=" + (terms == null ? "" : terms) + given(input, "terms-" + grade));
354	        });
355	        if (input.setsLatePct()) {
356	            repository.setLatePct(id, from(input, "late-pct", today), input.latePct());
357	            audit.record(prefix + "late-pct value=" + SettingsRepository.money(input.latePct()) + given(input, "late-pct"));
358	        }
359	        if (input.setsPolicyDate()) {
360	            repository.setPolicyDate(id, input.policyDate());
361	            audit.record(prefix + "policy-date value="
362	                    + (input.policyDate() == null ? "" : input.policyDate().toString()));
363	        }
364	        if (input.setsPeriodNumberingFrom()) {
365	            repository.setPeriodNumberingFrom(id, input.periodNumberingFrom());
366	            audit.record(prefix + "period-numbering-from value="
367	                    + (input.periodNumberingFrom() == null ? "" : input.periodNumberingFrom().toString()));
368	        }
369	        if (input.setsCap()) {
370	            repository.setCap(id, from(input, "cap", today), input.cap());
371	            audit.record(prefix + "cap value="
372	                    + (input.cap() == null ? "" : SettingsRepository.money(input.cap())) + given(input, "cap"));
373	        }
374	        rollup.record(id, by, before);
375	        settings.set(repository.load(id));
376	    }
377	
378	    private static LocalDate from(SettingsInput input, String key, LocalDate today) {
379	        return input.from().getOrDefault(key, today);
380	    }
381	
382	    private static String given(SettingsInput input, String key) {
383	        LocalDate from = input.from().get(key);
384	        return from == null ? "" : " from=" + from;
385	    }
386	}
