429	@Repository
430	public class SettingsRepository {
431	    public static final String CLERK = "clerk";
432	    public static final String STEWARD = "steward";
433	
434	    private final JdbcTemplate jdbc;
435	
436	    public SettingsRepository(JdbcTemplate jdbc) {
437	        this.jdbc = jdbc;
438	    }
439	
440	    public boolean sheetExists(String sheetId) {
441	        Integer known = jdbc.queryForObject("SELECT COUNT(*) FROM sheet WHERE id = ?", Integer.class, sheetId);
442	        return known != null && known > 0;
443	    }
444	
445	    /** The sheet's settings and roles, roles by user name: each dated setting as in force on the sheet's
446	     *  today, and every value recorded for each, by key. */
447	    public Settings load(String sheetId) {
448	        List<Role> roles = jdbc.query("SELECT user_name, role FROM sheet_role WHERE sheet_id = ? ORDER BY user_name",
449	                (rs, i) -> new Role(rs.getString("user_name"), rs.getString("role")), sheetId);
450	        LocalDate today = today(sheetId);
451	        BigDecimal limit = clerkLimit(sheetId);
452	        BigDecimal cap = cap(sheetId);
453	        LocalDate policy = policyDate(sheetId);
454	        LocalDate numbering = periodNumberingFrom(sheetId);
455	        return new Settings(limit == null ? null : money(limit), money(floor(sheetId, today)), terms(sheetId, today),
456	                money(latePct(sheetId, today)), roles, policy == null ? null : policy.toString(),
457	                numbering == null ? null : numbering.toString(), gradeTerms(sheetId, today),
458	                cap == null ? null : money(cap), dated(sheetId));
459	    }
460	
461	    /** The sheet's today; the real date when there is no such sheet. */
462	    private LocalDate today(String sheetId) {
463	        List<Date> found = jdbc.query("SELECT today FROM sheet WHERE id = ?", (rs, i) -> rs.getDate("today"), sheetId);
464	        return found.isEmpty() || found.get(0) == null ? LocalDate.now() : found.get(0).toLocalDate();
465	    }
466	
467	    /** The value of a dated setting in force on a date: the one recorded with the latest from-date on or
468	     *  before it (a list holding null when that one is blank); an empty list when none is recorded then. */
469	    private List<String> on(String sheetId, String key, LocalDate date) {
470	        List<String> found = new java.util.ArrayList<>();
471	        jdbc.query("SELECT setting FROM setting_value WHERE sheet_id = ? AND setting_key = ? AND from_date <= ?"
472	                + " ORDER BY from_date DESC LIMIT 1",
473	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> found.add(rs.getString("setting")),
474	                sheetId, key, Date.valueOf(date));
475	        return found;
476	    }
477	
478	    /** Record a dated setting's value from a date (null for blank), replacing one recorded from that date. */
479	    public void record(String sheetId, String key, LocalDate from, String value) {
480	        jdbc.update("MERGE INTO setting_value (sheet_id, setting_key, from_date, setting) KEY (sheet_id, setting_key, from_date)"
481	                + " VALUES (?, ?, ?, ?)", sheetId, key, Date.valueOf(from), value);
482	    }
483	
484	    /** Every value recorded for each dated setting, by key, each oldest from-date first. */
485	    public Map<String, List<DatedValue>> dated(String sheetId) {
486	        Map<String, List<DatedValue>> dated = new LinkedHashMap<>();
487	        jdbc.query("SELECT setting_key, from_date, setting FROM setting_value WHERE sheet_id = ? ORDER BY setting_key, from_date",
488	                (org.springframework.jdbc.core.RowCallbackHandler) rs -> dated
489	                        .computeIfAbsent(rs.getString("setting_key"), k -> new java.util.ArrayList<>())
490	                        .add(new DatedValue(rs.getDate("from_date").toLocalDate().toString(), rs.getString("setting"))),
491	                sheetId);
492	        return dated;
