661	/** Bind the settings form: the clerk limit is 0.00 or more with up to two decimals, blank meaning no
662	 *  limit; the floor is 0.00 or more with up to two decimals; the terms are a whole number of days, 0 to
663	 *  3650; the late percent is 0.00 or more with up to two decimals; the policy date is a date
664	 *  (yyyy-mm-dd), blank meaning the sheet's today; the period
665	 *  numbering from-date is a date, blank meaning off; a grade's (A, B or C) terms are like the sheet's, blank
666	 *  meaning the grade uses the sheet's terms; the cap is 0.00 or more with up to two decimals, blank meaning none. A from-date given for a
667	 *  setting with a figure is a date; blank is the sheet's today. A setting left out is not changed. */
668	public class ValidateSettings {
669	    private static final Pattern MONEY = Pattern.compile("\\d{1,9}(\\.\\d{1,2})?|\\.\\d{1,2}");
670	    private static final List<String> GRADES = List.of("A", "B", "C");
671	    private static final Pattern TERMS = Pattern.compile("\\d{1,4}");
672	
673	    public void validate(@RequestBody SettingsRequest request, Out<SettingsInput> settings)
674	            throws BadRequestException {
675	        String limit = request == null || request.clerkLimit() == null ? null : request.clerkLimit().trim();
676	        String floor = request == null || request.floor() == null ? null : request.floor().trim();
677	        String terms = request == null || request.terms() == null ? null : request.terms().trim();
678	        if (limit != null && !limit.isEmpty() && !MONEY.matcher(limit).matches()) {
679	            throw new BadRequestException("clerk limit must be 0.00 or more with up to two decimals");
680	        }
681	        if (floor != null && !MONEY.matcher(floor).matches()) {
682	            throw new BadRequestException("floor must be 0.00 or more with up to two decimals");
683	        }
684	        String latePct = request == null || request.latePct() == null ? null : request.latePct().trim();
685	        if (terms != null && (!TERMS.matcher(terms).matches() || Integer.parseInt(terms) > 3650)) {
686	            throw new BadRequestException("terms must be a whole number of days from 0 to 3650");
687	        }
688	        Map<String, Integer> gradeTerms = new LinkedHashMap<>();
689	        Map<String, String> grades = request == null || request.gradeTerms() == null ? Map.of() : request.gradeTerms();
690	        for (String grade : GRADES) {
691	            String value = grades.get(grade) == null ? null : grades.get(grade).trim();
692	            if (value == null) continue;
693	            if (!value.isEmpty() && (!TERMS.matcher(value).matches() || Integer.parseInt(value) > 3650)) {
694	                throw new BadRequestException("terms for grade " + grade + " must be a whole number of days from 0 to 3650");
695	            }
696	            gradeTerms.put(grade, value.isEmpty() ? null : Integer.parseInt(value));
697	        }
698	        for (String grade : grades.keySet()) {
699	            if (!GRADES.contains(grade)) throw new BadRequestException("grade must be A, B or C");
700	        }
701	        if (latePct != null && !MONEY.matcher(latePct).matches()) {
702	            throw new BadRequestException("late percent must be 0.00 or more with up to two decimals");
703	        }
704	        String cap = request == null || request.cap() == null ? null : request.cap().trim();
705	        if (cap != null && !cap.isEmpty() && !MONEY.matcher(cap).matches()) {
706	            throw new BadRequestException("cap must be 0.00 or more with up to two decimals");
707	        }
708	        String policy = request == null || request.policyDate() == null ? null : request.policyDate().trim();
709	        LocalDate policyDate = null;
710	        if (policy != null && !policy.isEmpty()) {
711	            try {
712	                policyDate = LocalDate.parse(policy);
713	            } catch (DateTimeParseException e) {
714	                throw new BadRequestException("policy date must be a date (yyyy-mm-dd)");
715	            }
716	        }
717	        String numbering = request == null || request.periodNumberingFrom() == null ? null
718	                : request.periodNumberingFrom().trim();
719	        LocalDate numberingFrom = null;
720	        if (numbering != null && !numbering.isEmpty()) {
721	            try {
722	                numberingFrom = LocalDate.parse(numbering);
723	            } catch (DateTimeParseException e) {
724	                throw new BadRequestException("period numbering from must be a date (yyyy-mm-dd)");
725	            }
726	        }
727	        Map<String, LocalDate> from = new LinkedHashMap<>();
728	        Map<String, String> froms = request == null || request.from() == null ? Map.of() : request.from();
729	        for (Map.Entry<String, String> given : froms.entrySet()) {
730	            String key = given.getKey();
731	            String date = given.getValue() == null ? "" : given.getValue().trim();
732	            if (date.isEmpty()) continue;
733	            boolean saved = switch (key) {
734	                case "clerk-limit" -> limit != null;
735	                case "floor" -> floor != null;
736	                case "terms" -> terms != null;
737	                case "late-pct" -> latePct != null;
738	                case "cap" -> cap != null;
739	                default -> key.startsWith("terms-") && gradeTerms.containsKey(key.substring(6));
740	            };
741	            if (!saved) continue;
742	            try {
743	                from.put(key, LocalDate.parse(date));
744	            } catch (DateTimeParseException e) {
745	                throw new BadRequestException("from-date for " + key + " must be a date (yyyy-mm-dd)");
746	            }
747	        }
748	        settings.set(new SettingsInput(limit != null,
749	                limit == null || limit.isEmpty() ? null : new BigDecimal(limit).setScale(2),
750	                floor != null, floor == null ? null : new BigDecimal(floor).setScale(2),
751	                terms != null, terms == null ? null : Integer.parseInt(terms),
752	                latePct != null, latePct == null ? null : new BigDecimal(latePct).setScale(2),
753	                policy != null, policyDate, numbering != null, numberingFrom, gradeTerms,
754	                cap != null, cap == null || cap.isEmpty() ? null : new BigDecimal(cap).setScale(2), from));
755	    }
756	}
