    public BigDecimal dueNow(String sheetId, Claim claim) {
        BigDecimal figure = figure(sheetId, claim);
        if (figure == null || !claim.open() || claim.deferred() || new BigDecimal(claim.amount()).signum() < 0) {
            return figure;
        }
